    "code": "/* Технология #355: Radar Sweep Pulse Scanner */\n// Движок: GSAP 3 | Кинетический декодер глифов\nconst ctx = canvas.getContext('2d');\nlet t = 0;\nconst glyphs = '01#@$%*&_ABCDEF';\nfunction draw() {\n  ctx.fillStyle = 'rgba(5, 5, 10, 0.2)';\n  ctx.fillRect(0, 0, canvas.width, canvas.height);\n  t += 0.05;\n  ctx.font = '13px JetBrains Mono, monospace';\n  const cols = 16, rows = 10;\n  const gx = canvas.width / cols, gy = canvas.height / rows;\n  for (let r = 0; r < rows; r++) {\n    for (let c = 0; c < cols; c++) {\n      const char = glyphs[Math.floor(Math.sin(r * 3 + c * 2 + t) * 50 + 50) % glyphs.length];\n      const alpha = Math.sin(c * 0.5 + t * 1.5 + r * 0.3);\n      ctx.fillStyle = alpha > 0.3 ? '#00f5d4' : (alpha > -0.2 ? '#4361ee' : 'rgba(255,255,255,0.08)');\n      ctx.fillText(char, c * gx + 6, r * gy + 16);\n    }\n  }\n  requestAnimationFrame(draw);\n}\ndraw();\nlog('Рендер наяву: Матричный декодер глифов (ID #355)');"
